# ---------- разбор транскриптов ----------

def result_text(p):
    t = p.get("content")
    if isinstance(t, list):
        t = " ".join(x.get("text", "") for x in t if isinstance(x, dict))
    return str(t or "")


def collect(run_dir):
    """Отклонения хуков: tool_result начинается с «PreToolUse:<Tool> hook error»."""
    files = [(p, None) for p in glob.glob(os.path.join(run_dir, "*.jsonl"))]
    for p in glob.glob(os.path.join(run_dir, "*", "subagents", "agent-*.jsonl")):
        files.append((p, os.path.basename(p)[len("agent-"):-len(".jsonl")]))
    out, seen = [], set()
    for path, agent_id in sorted(files, key=lambda x: x[0]):
        uses = {}
        with open(path, errors="replace") as f:
            for line in f:
                try:
                    d = json.loads(line)
                except Exception:
                    continue
                c = (d.get("message") or {}).get("content")
                if not isinstance(c, list):
                    continue
                for p in c:
                    if not isinstance(p, dict):
                        continue
                    if p.get("type") == "tool_use":
                        uses[p.get("id")] = p
                    elif p.get("type") == "tool_result" and re.match(r"\s*PreToolUse:\w+ hook error", result_text(p)):
                        u = uses.get(p.get("tool_use_id"))
                        if not u:
                            continue
                        key = (u["name"], json.dumps(u["input"], sort_keys=True), agent_id)
                        if key in seen:
                            continue
                        seen.add(key)
                        out.append({"tool": u["name"], "input": u["input"], "agent_id": agent_id,
                                    "by": "process-guard" if "process-guard.py" in result_text(p) else "guard"})
    return out


def group_of(e):
    if e["tool"] == "SubagentHandback":
        return "статус"
    if e["tool"] == "Agent":
        return "Agent"
    return "process-guard" if e["by"] == "process-guard" else "guard Bash"


# ---------- запуск хуков ----------

class Runner:
    def __init__(self, hooks_dir, tmp):
        self.pg = os.path.join(hooks_dir, "process-guard.py")
        self.wh = os.path.join(hooks_dir, "work_hooks.py")
        self.tmp = tmp
        self.home = os.path.join(tmp, "home")
        os.makedirs(self.home, exist_ok=True)
        self.cwd = os.path.join(tmp, "cwd")
        os.makedirs(self.cwd, exist_ok=True)
        open(os.path.join(self.cwd, ".env"), "w").write("API_KEY=stand\n")
        # worktree прогона удалены: подставляем пустой git-репозиторий, чтобы дошла проверка строк exit 0
        self.wt = os.path.join(tmp, "wt")
        os.makedirs(self.wt, exist_ok=True)
        for a in (["init", "-q"], ["-c", "user.name=s", "-c", "user.email=s@s", "commit", "-q", "--allow-empty", "-m", "x"]):
            subprocess.run(["git"] + a, cwd=self.wt, capture_output=True, stdin=subprocess.DEVNULL)
        self.head = subprocess.run(["git", "rev-parse", "HEAD"], cwd=self.wt, capture_output=True, text=True,
                                   stdin=subprocess.DEVNULL).stdout.strip()
        self.env = {k: v for k, v in os.environ.items() if k != "SOLO_SDD_EXPENSIVE_OK"}
        self.env["HOME"] = self.home

    def run(self, args, stdin):
        try:
            return subprocess.run([PY] + args, input=stdin, capture_output=True, text=True, timeout=20,
                                  env=self.env, cwd=self.cwd)
        except Exception as e:
            return subprocess.CompletedProcess(args, 3, "", "ошибка запуска: %r" % e)  # не 0: сбой не выдаётся за «пропущено»

    def process_guard(self, tool_input):
        r = self.run([self.pg], json.dumps({"tool_name": "Bash", "tool_input": tool_input}))
        return (r.stderr or r.stdout).strip() or "код %d" % r.returncode if r.returncode else None

    def guard(self, e):
        ti = e["input"]
        if e["tool"] == "SubagentHandback":
            ti = dict(ti, message=re.sub(r"(?m)^(\s*WORKTREE:).*$", lambda m: m.group(1) + " " + self.wt, ti.get("message", "")))
            # остальные поля сводим к стенду: COMMIT — HEAD пустого репозитория, ARCHIVE — папка в нём
            ti["message"] = re.sub(r"(?m)^(\s*COMMIT:).*$", lambda m: m.group(1) + " " + self.head, ti["message"])
            arch = re.search(r"(?m)^\s*ARCHIVE:\s*(\S+)", ti["message"])
            if arch:
                rel = "openspec/changes/archive/" + arch.group(1).split("openspec/changes/archive/")[-1].strip("/")
                os.makedirs(os.path.join(self.wt, rel), exist_ok=True)
                ti["message"] = ti["message"].replace(arch.group(0), arch.group(0).replace(arch.group(1), rel))
        inp = {"tool_name": e["tool"], "tool_input": ti, "session_id": "hooks-replay", "cwd": self.cwd}
        if e.get("agent_id"):
            inp["agent_id"] = e["agent_id"]
        r = self.run([self.wh, "guard"], json.dumps(inp))
        try:
            h = json.loads(r.stdout)["hookSpecificOutput"]
            return h["permissionDecisionReason"] if h.get("permissionDecision") == "deny" else None
        except Exception:
            return None

    def verdict(self, e):
        """(хук, причина) первого отказавшего хука или None."""
        if e["tool"] == "Bash":
            why = self.process_guard(e["input"])
            if why:
                return "process-guard", why
        why = self.guard(e)
        return ("guard", why) if why else None


def exit0_line(why):
    """Строка про VALIDATE/TESTS, если она есть, иначе вся причина."""
    m = re.search(r"(?m)^- ((?:VALIDATE|TESTS):.*)$", why)
    return m.group(1) if m else why


def short(s):
    return re.sub(r"\s+", " ", s)[:80]


# ---------- stop ----------

def stop_checks(rt, run_dir):
    """Две проверки Stop: с симлинком subagents (причины нет) и без него (причина есть, если применимо)."""
    main = os.path.join(run_dir, MAIN_ID + ".jsonl")
    res = []
    if not os.path.exists(main):
        return [("stop", "нет главного транскрипта", None, "пропущено", False)]
    work = os.path.join(rt.tmp, "stop")
    os.makedirs(work, exist_ok=True)
    app = os.path.join(rt.cwd, "App.tsx")
    open(app, "w").write("export {}\n")
    extra = json.dumps({"type": "assistant", "message": {"role": "assistant", "content": [
        {"type": "tool_use", "id": "toolu_replay", "name": "Edit", "input": {"file_path": app, "old_string": "a", "new_string": "b"}}]}})

    def one(name, link):
        d = os.path.join(work, name)
        os.makedirs(d, exist_ok=True)
        tp = os.path.join(d, MAIN_ID + ".jsonl")
        shutil.copyfile(main, tp)
        with open(tp, "a") as f:
            f.write(extra + "\n")
        if link:
            os.makedirs(os.path.join(d, MAIN_ID), exist_ok=True)
            os.symlink(os.path.join(run_dir, MAIN_ID, "subagents"), os.path.join(d, MAIN_ID, "subagents"))
        inp = {"session_id": "hooks-replay-stop-" + uuid.uuid4().hex[:8], "cwd": rt.cwd, "transcript_path": tp,
               "last_assistant_message": "Готово, всё проверено по-русски, отчёт ниже."}
        r = rt.run([rt.wh, "stop"], json.dumps(inp))
        try:
            return json.loads(r.stdout).get("reason", "")
        except Exception:
            return ""

    with_link = one("with", True)
    ok = "Изменён интерфейс" not in with_link
    res.append(("stop", "с subagents", "без причины «Изменён интерфейс»",
                "пропущено" if ok else "отклонено (%s)" % short(with_link), ok))
    without = one("without", False)
    has = "Изменён интерфейс" in without
    main_browser = "agent-browser" in open(main, errors="replace").read() or "mcp__claude-in-chrome" in open(main, errors="replace").read()
    if has:
        res.append(("контроль", "stop без subagents", "причина есть", "отклонено (%s)" % short(without), True))
    elif main_browser:
        res.append(("контроль", "stop без subagents", "причина есть", "неприменим: в главном транскрипте есть признаки браузера", True))
    else:
        res.append(("контроль", "stop без subagents", "причина есть", "пропущено", False))
    return res


# ---------- основной ход ----------

def main(argv):
    hooks, run_dir, args = os.path.join(REAL_HOME, ".claude/hooks"), DEFAULT_RUN, argv[:]
    if "--hooks" in args:
        i = args.index("--hooks")
        hooks = os.path.abspath(args[i + 1])
        del args[i:i + 2]
    if args:
        run_dir = os.path.abspath(os.path.expanduser(args[0]))
    for n in ("process-guard.py", "work_hooks.py"):
        if not os.path.exists(os.path.join(hooks, n)):
            print("Нет %s в %s" % (n, hooks))
            return 2
    if os.path.isdir(run_dir):
        entries, src = collect(run_dir), "транскрипты " + run_dir
    else:
        entries, src = BUILTIN, "BUILTIN (папки %s нет)" % run_dir
    print("Хуки: %s\nВходы: %s, найдено отказов: %d" % (hooks, src, len(entries)))

    tmp = tempfile.mkdtemp(prefix="hooks-replay-")
    stats = {g: [0, 0] for g in GROUPS}
    rows = []
    try:
        rt = Runner(hooks, tmp)
        for e in entries:
            g = group_of(e)
            v = rt.verdict(e)
            where = "sub:" + e["agent_id"][:8] if e.get("agent_id") else "main"
            if g == "статус":
                # исправлено: пропущено или отказ без строки про VALIDATE/TESTS «exit 0»
                line = v is not None and re.search(r"(?m)^- (VALIDATE|TESTS):", v[1])
                if re.search(r"(?m)^(VALIDATE|TESTS):.* -> exit [1-9]", e["input"].get("message", "")):
                    # честный провал: в статусе сам exit != 0, хук обязан отклонить со строкой про VALIDATE/TESTS
                    ok, exp = bool(line), "отклонено: exit≠0 (строка про VALIDATE/TESTS)"
                else:
                    ok, exp = v is None, "пропущено"
            else:
                ok, exp = v is None, "пропущено"
            res = "пропущено" if v is None else "отклонено %s (%s)" % (v[0], short(exit0_line(v[1]) if g == "статус" else v[1]))
            rows.append((g, "%s  %s  %s  %s  %s" % (where, e["by"] if g != "статус" else "guard", exp, res, "OK" if ok else "FAIL")))
            stats[g][0] += ok
            stats[g][1] += 1
        for g, e in CONTROLS:
            v = rt.verdict(e)
            want = "process-guard" if g == "process-guard" else "guard"
            ok = v is not None and v[0] == want
            res = "пропущено" if v is None else "отклонено %s (%s)" % (v[0], short(v[1]))
            rows.append(("контроль", "control  %s  отклонено  %s  %s" % (want, res, "OK" if ok else "FAIL")))
            stats["контроль"][0] += ok
            stats["контроль"][1] += 1
        for g, hook, exp, res, ok in stop_checks(rt, run_dir) if os.path.isdir(run_dir) else []:
            rows.append((g, "main  %s  %s  %s  %s" % (hook, exp, res, "OK" if ok else "FAIL")))
            stats[g][0] += ok
            stats[g][1] += 1
        # хуки fail-open: внутренняя ошибка пропускает действие и видна только в errors.log
        elog = os.path.join(rt.home, ".claude/hook-state/errors.log")
        hook_errors = open(elog).read() if os.path.exists(elog) else ""
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    for _, line in rows:
        print(line)
    print("\nСводка (прошло по ожиданию / всего):")
    for g in GROUPS:
        print("  %-14s %d / %d" % (g, *stats[g]))
    bad = sum(t - o for o, t in stats.values())
    if hook_errors:
        print("\nОшибки хуков (errors.log), каждая — FAIL:\n" + hook_errors)
        bad += len(hook_errors.splitlines())
    print("Итого FAIL: %d" % bad)
    return 0 if bad == 0 else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
